/// Return the accepted index of this node's log (as if it was never compacted).
/// Equal to the index of the last accepted entry; useful for tagging a just-appended
/// entry so that decision can be awaited.
pub fn get_accepted_idx(&self) -> usize {
    self.seq_paxos.internal_storage.get_accepted_idx()
}

/// Read all decided entries starting at `from_idx` (inclusive) in the log. Returns `None` if `from_idx` is out of bounds.
pub fn read_decided_suffix(&self, from_idx: usize) -> Option<Vec<LogEntry<T>>> {
    self.seq_paxos
        .internal_storage
        .read_decided_suffix(from_idx)
        .expect("storage error while trying to read decided log suffix")
